  'Copy link': 'Sao chép liên kết',
  'Create a passkey on this device for the profile “{0}”. It signs you in here from now on.': 'Tạo passkey trên thiết bị này cho hồ sơ “{0}”. Bạn sẽ dùng nó để đăng nhập tại đây từ bây giờ.',
  'Each one signs in to this profile from the device or password manager that keeps it. Tap one to rename or remove it.': 'Mỗi passkey cho phép đăng nhập vào hồ sơ này từ thiết bị hoặc trình quản lý mật khẩu lưu trữ nó. Nhấn vào một mục để đổi tên hoặc xóa.',
  'Enter the code from your other device.': 'Nhập mã từ thiết bị khác của bạn.',
  'For this device, a security key, a password manager, or your phone through the browser’s own QR code. First confirm that it is you.': 'Dành cho thiết bị này, khóa bảo mật, trình quản lý mật khẩu hoặc điện thoại của bạn qua mã QR của trình duyệt. Trước tiên, hãy xác nhận danh tính của bạn.',
  'It can no longer sign in to this profile. A device already signed in with it stays signed in. If it was lost, use Sign out everywhere.': 'Passkey này không còn dùng để đăng nhập vào hồ sơ này được nữa. Thiết bị đã đăng nhập bằng passkey này vẫn duy trì trạng thái đăng nhập. Nếu bị mất thiết bị, hãy dùng Đăng xuất khỏi mọi nơi.',
  'It is your only way in, so it cannot be removed until there is another.': 'Đây là cách duy nhất để đăng nhập, vì vậy không thể xóa cho đến khi có phương thức khác.',
