  'Scan this with the other device, or open openGym there and enter the code on the sign-in screen. It works once, for {0} minutes.': 'Quét mã này bằng thiết bị khác, hoặc mở openGym trên thiết bị đó và nhập mã tại màn hình đăng nhập. Mã dùng được một lần và có hiệu lực trong {0} phút.',
  'That code is wrong, already used or expired. Make a new one on your other device.': 'Mã không đúng, đã được sử dụng hoặc đã hết hạn. Hãy tạo mã mới trên thiết bị khác của bạn.',
  'This browser cannot confirm with your passkey. Do this on a device that holds one.': 'Trình duyệt này không thể xác nhận bằng passkey. Hãy thực hiện thao tác trên thiết bị đang lưu trữ passkey.',
