  'This profile has no passkey, and this server does not take passwords, so nothing here can confirm that it is you. Ask your admin.': 'Hồ sơ này không có passkey và máy chủ không nhận mật khẩu, vì vậy không thể xác minh danh tính của bạn. Hãy liên hệ quản trị viên.',
  'This browser cannot create passkeys, so it cannot be added with a code. Open the link in a browser that can.': 'Trình duyệt này không thể tạo passkey, do đó không thể thêm bằng mã. Hãy mở liên kết trong trình duyệt có hỗ trợ.',
  'This browser is signed in as “{0}”. Adding it to “{1}” signs “{0}” out here.': 'Trình duyệt này đang đăng nhập dưới tên “{0}”. Thêm vào “{1}” sẽ đăng xuất “{0}” tại đây.',
  'This code is for a different profile that is also called “{0}”, not the one this browser is signed in as. Adding it there signs yours out here.': 'Mã này dành cho một hồ sơ khác cũng có tên “{0}”, không phải hồ sơ đang đăng nhập trên trình duyệt này. Thêm vào đó sẽ đăng xuất tài khoản hiện tại của bạn tại đây.',
  'Only continue if this code comes from a device of your own. This browser is then signed in to “{0}”, and what you log here goes to that profile.': 'Chỉ tiếp tục nếu mã này đến từ thiết bị của chính bạn. Sau đó, trình duyệt này sẽ đăng nhập vào “{0}”, và toàn bộ dữ liệu bạn ghi nhận tại đây sẽ thuộc về hồ sơ đó.',
  'This code has expired.': 'Mã này đã hết hạn.',
