  'Saves a dated copy to Documents/openGym after finishing a workout or editing a routine, and keeps the newest {0}. Point a sync app at that folder, or copy it out by hand.': 'Lưu bản sao có ghi ngày vào Documents/openGym sau khi hoàn thành buổi tập hoặc chỉnh sửa lịch tập, và giữ lại {0} bản mới nhất. Hãy liên kết ứng dụng đồng bộ vào thư mục đó, hoặc sao chép thủ công.',
  'Reset everything?': 'Đặt lại tất cả?',
  'Reset everything': 'Đặt lại tất cả',
  'Deletes your plan, workouts, body weight, photos and videos on this device. This cannot be undone.': 'Xóa kế hoạch tập, buổi tập, thể trọng, hình ảnh và video trên thiết bị này. Không thể hoàn tác.',
  'Deletes your plan, workouts, body weight, photos and videos from your profile on this server and on every signed-in device. This cannot be undone.': 'Xóa kế hoạch tập, buổi tập, thể trọng, hình ảnh và video khỏi hồ sơ của bạn trên máy chủ này và trên mọi thiết bị đã đăng nhập. Không thể hoàn tác.',
  'Sync failed: the server refused the upload as too large. Your changes have not reached the server.': 'Đồng bộ thất bại: máy chủ từ chối do tệp tải lên quá lớn. Các thay đổi của bạn chưa được lưu lên máy chủ.',
  'This device is out of storage: the change is not saved on it. Signed in, it still goes to the server.': 'Thiết bị này đã hết dung lượng: thay đổi không thể lưu trên máy. Nếu đã đăng nhập, dữ liệu vẫn được lưu lên máy chủ.',
