  'Print / Save as PDF': 'In / Lưu dưới dạng PDF',
  'Add an exercise to a routine first. An empty plan has nothing to share.': 'Hãy thêm bài tập vào lịch tập trước. Kế hoạch trống không có gì để chia sẻ.',
