  'These are added as new routines. Nothing you already have is touched.': 'Các mục này được thêm vào làm lịch tập mới. Dữ liệu hiện có của bạn sẽ không bị ảnh hưởng.',
  '{0} exercise in the file isn’t in your library and was left out.': '{0} bài tập trong tệp không có trong thư viện của bạn và đã được bỏ qua.',
  '{0} exercises in the file aren’t in your library and were left out.': '{0} bài tập trong tệp không có trong thư viện của bạn và đã được bỏ qua.',
  'Use this weekly schedule': 'Sử dụng lịch tuần này',
