  'How long is a session?': 'Mỗi buổi tập kéo dài bao lâu?',
  'min': 'phút',
  'The Coach fits the volume to the time you actually have, including rest between sets.': 'Huấn luyện viên sẽ điều chỉnh khối lượng tập phù hợp với thời gian thực tế của bạn, bao gồm cả thời gian nghỉ giữa các hiệp.',
  'What can you train with?': 'Bạn có những dụng cụ tập luyện nào?',
  'Pick everything you have access to. Leave it empty and the Coach will use the whole library.': 'Hãy chọn tất cả dụng cụ bạn có thể sử dụng. Nếu để trống, Huấn luyện viên sẽ dùng toàn bộ thư viện bài tập.',
  'Anything to work around?': 'Có hạn chế nào cần lưu ý không?',
  'Injuries, joints that complain, movements you cannot do, or practical limits like training at 6am in a flat.': 'Chấn thương, khớp bị đau, động tác không thể tập, hoặc các hạn chế thực tế như tập lúc 6 giờ sáng trong căn hộ chung cư.',
  'e.g. “dodgy left shoulder, no barbell overhead press”': 'ví dụ: “vai trái có vấn đề, không tập đẩy tạ đòn qua đầu”',
  'If something actually hurts, see a professional. The Coach will program conservatively, but it can’t diagnose anything.': 'Nếu bạn thực sự bị đau nhức, hãy tham khảo ý kiến chuyên gia y tế. Huấn luyện viên sẽ lên lịch tập một cách an toàn, nhưng không thể chẩn đoán bệnh lý.',
  'Anything else?': 'Còn điều gì khác không?',
  'Exercises you love': 'Các bài tập bạn yêu thích',
  'e.g. “deadlifts, anything with a kettlebell”': 'ví dụ: “deadlift, mọi bài tập với tạ chuông (kettlebell)”',
  'Exercises you would rather not': 'Các bài tập bạn không muốn tập',
  'e.g. “I hate lunges”': 'ví dụ: “Tôi ghét lunge”',
  'Anything you want the Coach to know': 'Điều bạn muốn Huấn luyện viên biết thêm',
  'e.g. “I want visible arms progress by spring”': 'ví dụ: “Tôi muốn thấy bắp tay phát triển rõ rệt trước mùa xuân”',
  'Build my plan': 'Tạo kế hoạch cho tôi',
