  'That proposal can’t be read.': 'Không thể đọc đề xuất đó.',
  'Discard this plan?': 'Hủy bỏ kế hoạch này?',
  'Nothing is saved, and you can ask again anytime.': 'Không có gì được lưu lại và bạn có thể yêu cầu tạo lại bất kỳ lúc nào.',
  'Revision {0}': 'Bản chỉnh sửa {0}',
  'Replaces your current week. Days this plan leaves empty become rest days.': 'Thay thế tuần tập hiện tại của bạn. Những ngày để trống trong kế hoạch này sẽ trở thành ngày nghỉ.',
  'Could not apply those changes': 'Không thể áp dụng các thay đổi đó',
  'Dismiss these suggestions?': 'Bỏ qua các đề xuất này?',
  'Nothing changes, and the Coach will remember you turned these down.': 'Sẽ không có gì thay đổi và Huấn luyện viên sẽ ghi nhớ rằng bạn đã từ chối các đề xuất này.',
  'Dismiss': 'Bỏ qua',
  'Based on your last {0} sessions': 'Dựa trên {0} buổi tập gần nhất của bạn',
  'Your plan changed since the Coach looked at it. Suggestions that no longer match are greyed out. Ask for a fresh review to see them again.': 'Kế hoạch của bạn đã thay đổi kể từ lần xem xét trước của Huấn luyện viên. Các đề xuất không còn phù hợp sẽ bị làm mờ. Hãy yêu cầu đánh giá mới để cập nhật lại.',
  'Doesn’t match your plan any more, so it can’t be applied.': 'Không còn phù hợp với kế hoạch của bạn nữa, nên không thể áp dụng.',
