  'On the openGym app, choose “Connect to my server”, then enter this address and the code below. It expires in 5 minutes.': 'Trên ứng dụng openGym, chọn “Kết nối với máy chủ của tôi”, sau đó nhập địa chỉ này và mã bên dưới. Mã sẽ hết hạn sau 5 phút.',
