  'Local keeps everything on this phone. Connecting syncs to your own openGym server instead. You can switch later in Settings.': 'Chế độ cục bộ sẽ lưu mọi thứ trên điện thoại này. Kết nối sẽ đồng bộ với máy chủ openGym của riêng bạn. Bạn có thể thay đổi sau trong Cài đặt.',
  '{0} (done)': '{0} (hoàn thành)',
  'Workout done': 'Buổi tập hoàn tất',
  'reps': 'reps',
  'Most reps in a set per workout': 'Số reps nhiều nhất trong một hiệp mỗi buổi tập',
  'Warm-up sets': 'Hiệp khởi động',
  'Added before your work sets and left out of volume, records and progression. Each one closes half the gap to the work weight, never below the bar on a barbell lift, and you can still change any of them mid-session.': 'Được thêm trước các hiệp chính và không tính vào khối lượng tập, kỷ lục và tiến trình. Mỗi hiệp thu hẹp một nửa mức tạ chênh lệch tới mức tạ chính, không bao giờ nhẹ hơn đòn khi tập tạ đòn, và bạn vẫn có thể chỉnh sửa bất cứ lúc nào trong buổi tập.',
  'Ramp-up sets added before the work sets, so you do not have to add them by hand each session.': 'Các hiệp tăng dần mức tạ được thêm trước hiệp chính, giúp bạn không cần phải thêm thủ công mỗi buổi tập.',
  'Note': 'Ghi chú',
