  'Rest-pause always trains as one warm-up set at this rep count, then one rest-pause work set. "Sets" isn’t used here.': 'Rest-pause luôn gồm một hiệp khởi động ở số reps này, tiếp theo là một hiệp chính rest-pause. Thuật ngữ "Hiệp" không được dùng ở đây.',
