  'Could not reach the provider: {0}': 'Không thể kết nối với nhà cung cấp: {0}',
  'Android blocks unencrypted http:// connections from apps, so this phone can only reach an https:// endpoint. Put HTTPS in front of it (Tailscale or a reverse proxy), or choose “Use my self-hosted openGym”: your server can reach an http:// model on its own network.': 'Android chặn các kết nối http:// không mã hóa từ ứng dụng, do đó điện thoại này chỉ có thể truy cập endpoint https://. Hãy đặt HTTPS phía trước (dùng Tailscale hoặc reverse proxy), hoặc chọn “Dùng openGym tự lưu trữ của tôi”: máy chủ của bạn có thể truy cập mô hình http:// trong mạng nội bộ.',
  'Each request goes straight to {0} with your key. Nobody else sees it, and you pay for it.': 'Mỗi yêu cầu được gửi trực tiếp đến {0} bằng key của bạn. Không ai khác có thể xem dữ liệu và bạn tự thanh toán chi phí này.',
  'Endpoint': 'Endpoint',
  'Enter your API key': 'Nhập API key của bạn',
  'Enter the endpoint URL': 'Nhập URL endpoint',
  'There’s no routine to review yet. Build one with at least two exercises first.': 'Chưa có lịch tập nào để đánh giá. Hãy tạo một lịch tập có ít nhất hai bài tập trước.',
  'How should the Coach run?': 'HLV AI sẽ hoạt động như thế nào?',
