  'Pick a model': 'Chọn một mô hình',
  'Provider': 'Nhà cung cấp',
  'Runs on this phone with your own API key': 'Chạy trên điện thoại này với API key của bạn',
  'Runs on your openGym server': 'Chạy trên máy chủ openGym của bạn',
  'Save and use the Coach': 'Lưu và sử dụng HLV AI',
