  'The Coach is taking a breather. You’ve used today’s {0} runs on this phone.': 'HLV AI đang nghỉ ngơi một chút. Bạn đã dùng hết {0} lượt hôm nay trên thiết bị này.',
  'The Coach isn’t set up on this phone.': 'HLV AI chưa được thiết lập trên điện thoại này.',
