  'The key is stored in this phone’s secure storage and never leaves it except to call the provider.': 'Khóa API được lưu trữ an toàn trên điện thoại này và không bao giờ gửi ra ngoài ngoại trừ khi gọi tới nhà cung cấp.',
  'This phone calls the provider directly with your key. Every request is charged to your account.': 'Điện thoại này gọi trực tiếp tới nhà cung cấp bằng khóa của bạn. Mỗi yêu cầu sẽ được tính phí vào tài khoản của bạn.',
  'Turn the Coach off on this phone': 'Tắt Huấn luyện viên trên điện thoại này',
  'Use my self-hosted openGym': 'Dùng máy chủ openGym tự lưu trữ của tôi',
  'What leaves this phone': 'Dữ liệu được gửi khỏi điện thoại này',
  'Your server has no Coach enabled. Ask its admin, or bring your own key below.': 'Máy chủ của bạn chưa bật Huấn luyện viên. Hãy hỏi quản trị viên hoặc tự nhập API key bên dưới.',
  'Your server runs the Coach with whatever provider its admin set up. Nothing new leaves this phone beyond what already syncs.': 'Máy chủ chạy Huấn luyện viên qua nhà cung cấp do quản trị viên thiết lập. Không có dữ liệu mới nào gửi ra ngoài ngoại trừ những dữ liệu vốn đã đồng bộ.',
