  'Start a new plan': 'Bắt đầu kế hoạch mới',
  'A fresh plan from your answers; your workouts stay': 'Kế hoạch hoàn toàn mới từ câu trả lời của bạn; giữ nguyên các buổi tập cũ',
  'Build me a fresh plan from my answers.': 'Hãy lập kế hoạch mới dựa trên các câu trả lời của tôi.',
  'Experience': 'Kinh nghiệm',
  'Goal, days, equipment, limits': 'Mục tiêu, số ngày, thiết bị, giới hạn',
  'Have a look at my training and tell me what you would change.': 'Hãy xem qua quá trình tập của tôi và cho biết bạn muốn thay đổi điều gì.',
  'Here is what I am working with:': 'Dưới đây là các thông tin tôi đang có:',
  'Hi, I’m your Coach. I build your plan from your answers and adjust it from what you actually log. Nothing changes until you say so.': 'Xin chào, tôi là Huấn luyện viên của bạn. Tôi lập kế hoạch từ các câu trả lời của bạn và điều chỉnh theo nhật ký tập luyện thực tế. Sẽ không có gì thay đổi nếu bạn chưa đồng ý.',
  'I looked through everything and there is nothing I would change right now. Keep it up, and ask me again after a few more sessions.': 'Tôi đã xem qua mọi thứ và hiện tại không có gì cần thay đổi. Hãy tiếp tục phát huy và hỏi lại tôi sau vài buổi tập nữa nhé.',
  'I understand, let’s go': 'Tôi hiểu rồi, bắt đầu thôi',
  'Imported! {0} routines are in your plan and your week is set. See you at the next session.': 'Đã nhập! {0} lịch tập đã có trong kế hoạch và tuần tập của bạn đã sẵn sàng. Hẹn gặp lại ở buổi tập tiếp theo.',
  'Imported! {0} routines are in your plan. Your week is unchanged; schedule them whenever you like.': 'Đã nhập! {0} lịch tập đã có trong kế hoạch. Tuần tập của bạn vẫn giữ nguyên; hãy xếp lịch bất cứ khi nào bạn muốn.',
  'It designs your plan from a few answers and adjusts it from what you actually log. It never changes anything without your say-so, and you can undo every change.': 'Hệ thống thiết kế kế hoạch tập từ vài câu trả lời và điều chỉnh dựa trên nhật ký thực tế của bạn. Sẽ không có gì bị thay đổi khi chưa có sự đồng ý của bạn, và bạn có thể hoàn tác mọi thay đổi.',
  'Routines, exercises, sets and reps, your weekly schedule and progression settings.': 'Lịch tập, bài tập, hiệp và reps, lịch trình hàng tuần cùng cài đặt tăng tiến.',
  'Your logged training': 'Nhật ký tập luyện của bạn',
  'Sets you logged in the review window: weights, reps, times, effort ratings, how long sessions took, and your session notes.': 'Các hiệp bạn đã ghi trong khoảng thời gian đánh giá: mức tạ, reps, thời gian, đánh giá mức độ gắng sức, thời lượng buổi tập và ghi chú buổi tập.',
  'Weigh-ins from the same window, and your goal weight if you set one.': 'Các lần cân nặng trong cùng khoảng thời gian đó, và cân nặng mục tiêu nếu bạn có thiết lập.',
  'What you tell the Coach': 'Những gì bạn trao đổi với Huấn luyện viên',
  'Your intake answers, including any limitations or injuries you describe.': 'Câu trả lời khảo sát ban đầu của bạn, bao gồm mọi giới hạn hoặc chấn thương bạn đã mô tả.',
  'A few preferences': 'Một vài tùy chọn cá nhân',
  'Your unit, your language and which effort scale you log.': 'Đơn vị đo, ngôn ngữ và thang đo mức độ gắng sức bạn dùng.',
  'Likes: {0}': 'Yêu thích: {0}',
  'Limits': 'Giới hạn',
  'Limits: {0}': 'Giới hạn: {0}',
  'Not quite right? Say what to change below and I will revise the whole plan.': 'Chưa hoàn toàn ưng ý? Hãy cho biết cần thay đổi gì ở bên dưới và tôi sẽ chỉnh sửa lại toàn bộ kế hoạch.',
  'Pick one to continue.': 'Chọn một mục để tiếp tục.',
  'Pick what you will actually keep, not the best week you can imagine.': 'Hãy chọn lịch trình bạn thực sự có thể duy trì, thay vì một tuần hoàn hảo chỉ có trong tưởng tượng.',
  'Reading your training…': 'Đang đọc dữ liệu tập luyện…',
  'Schedule': 'Lịch trình',
  'Send': 'Gửi',
  'Sent straight to {0} with your own API key. You pay for every request.': 'Được gửi trực tiếp tới {0} bằng API key của bạn. Bạn sẽ trả phí cho từng yêu cầu.',
  'Sent to {0}, running on this server under the instance owner’s account.': 'Được gửi tới {0}, chạy trên máy chủ này dưới tài khoản của chủ sở hữu instance.',
  'Session length': 'Thời lượng buổi tập',
  'Sets the pace of progression, and how much the Coach assumes you know.': 'Thiết lập tốc độ tăng tiến và mức độ kiến thức mà Huấn luyện viên ước lượng bạn đã có.',
  'Suggestions': 'Gợi ý',
  'The Coach builds the whole plan around this.': 'Huấn luyện viên sẽ xây dựng toàn bộ kế hoạch xoay quanh điều này.',
  'This usually takes a minute or two.': 'Quá trình này thường mất khoảng một hoặc hai phút.',
  'Got it. I won’t suggest these again without new evidence.': 'Đã hiểu. Tôi sẽ không gợi ý lại những điều này trừ khi có dữ liệu mới.',
  'Usually about {0} min.': 'Thường khoảng {0} phút.',
