  'Nothing yet. Every plan, suggestion and debrief will be kept here, whether you said yes or no.': 'Chưa có gì. Mọi lịch tập, gợi ý và tổng kết buổi tập sẽ được lưu tại đây, dù bạn đồng ý hay từ chối.',
