  'Only medians across everyone who shares, never a name, a body weight or a single session. Turning this off removes you from the numbers immediately.': 'Chỉ tính trung vị từ tất cả người chia sẻ, không bao giờ hiển thị tên, thể trọng hay buổi tập cụ thể. Tắt tùy chọn này sẽ xóa bạn khỏi dữ liệu ngay lập tức.',
