  'Top sets logged without an effort rating; add RIR so the next review can read how hard they were.': 'Các hiệp top set chưa có đánh giá mức độ nỗ lực; hãy thêm RIR để lần đánh giá tới có thể phân tích độ nặng của hiệp.',
