  'A clean session: everything on the sheet got done and the loads held. This is exactly what progress looks like from the inside: unremarkable, repeated.': 'Một buổi tập chỉn chu: hoàn thành mọi thứ trong giáo án và duy trì mức tạ. Đây chính là bản chất của sự tiến bộ: không ồn ào, chỉ là sự lặp lại bền bỉ.',
  'Most of the work got done. One or two sets fell short, which is fine once. It only becomes a signal if the same sets miss next time.': 'Đã hoàn thành phần lớn khối lượng tập. Hụt một hoặc hai hiệp là bình thường nếu chỉ xảy ra một lần. Nó chỉ đáng lưu ý nếu lần tới bạn vẫn không hoàn thành các hiệp tương tự.',
