  'Pairs of each size you own. Every set row loads from this list, so a home gym with one pair of 45s is never told to use two.': 'Số cặp bánh tạ của từng cỡ bạn sở hữu. Mỗi hiệp tập sẽ gợi ý dựa trên danh sách này, ví dụ nếu phòng gym tại nhà chỉ có một cặp bánh 45 lb thì hệ thống sẽ không bao giờ yêu cầu dùng hai cặp.',
  'pairs': 'cặp',
  'Your own list for {0}.': 'Danh sách bánh tạ riêng của bạn cho {0}.',
  'The standard set, plenty of each. Change any count to make it yours.': 'Bộ bánh tạ tiêu chuẩn, có đủ số lượng mỗi loại. Điều chỉnh số lượng bất kỳ theo trang bị của bạn.',
  'Back to the standard set': 'Quay lại bộ tiêu chuẩn',
  'Standard set. Tap to count the pairs you own.': 'Bộ tiêu chuẩn. Nhấn để nhập số cặp bạn sở hữu.',
  'You still log the total weight. This only feeds the plate line under each set.': 'Bạn vẫn ghi nhận tổng mức tạ. Thiết lập này chỉ dùng để hiển thị gợi ý lắp bánh tạ dưới mỗi hiệp.',
  'Default for this bar type.': 'Mặc định cho loại thanh đòn này.',
  'No bar': 'Không dùng thanh đòn',
  'The weight you log is all plates.': 'Mức tạ bạn ghi nhận hoàn toàn là bánh tạ.',
  'Plates are counted from 0. Turn this off for the default ({0}).': 'Bánh tạ được tính từ 0. Tắt tùy chọn này để áp dụng mặc định ({0}).',
  'Set to 0 to go back to the default ({0}).': 'Đặt về 0 để quay lại mức mặc định ({0}).',
  'Applies to this exercise everywhere, not just this plan.': 'Áp dụng cho bài tập này ở mọi nơi, không chỉ riêng lịch tập này.',
