  '{0} workout and {1} weigh-in were logged on this device while signed out. Add them to your profile, or keep the profile exactly as it is on the server.': '{0} buổi tập và {1} lần cân đã được ghi nhận trên thiết bị này khi đăng xuất. Thêm vào hồ sơ của bạn, hoặc giữ nguyên hồ sơ trên máy chủ.',
  '{0} workout and {1} weigh-ins were logged on this device while signed out. Add them to your profile, or keep the profile exactly as it is on the server.': '{0} buổi tập và {1} lần cân đã được ghi nhận trên thiết bị này khi đăng xuất. Thêm vào hồ sơ của bạn, hoặc giữ nguyên hồ sơ trên máy chủ.',
