  'Offline. Your changes are saved on this device and sync when you’re back online.': 'Ngoại tuyến. Các thay đổi được lưu trên thiết bị này và sẽ đồng bộ khi có mạng trở lại.',
  'Offline. Showing the last copy synced with the server.': 'Ngoại tuyến. Đang hiển thị bản sao đồng bộ gần nhất với máy chủ.',
