  'Your server’s address answered with something other than openGym (HTTP {0}). Your changes are kept here.': 'Địa chỉ máy chủ của bạn phản hồi dữ liệu không phải của openGym (HTTP {0}). Các thay đổi vẫn được lưu tại đây.',
