  'The server refuses this browser': 'Máy chủ từ chối trình duyệt này',
  'Your server no longer accepts this browser. Your changes are kept here.': 'Máy chủ của bạn không còn chấp nhận trình duyệt này nữa. Các thay đổi vẫn được lưu tại đây.',
  'This phone is no longer paired with your server. Your changes are kept here.': 'Điện thoại này không còn được ghép nối với máy chủ của bạn. Các thay đổi vẫn được lưu tại đây.',
  'The server refuses this phone': 'Máy chủ từ chối điện thoại này',
  'Your server no longer accepts this phone. Your changes are kept here.': 'Máy chủ của bạn không còn chấp nhận điện thoại này nữa. Các thay đổi vẫn được lưu tại đây.',
  'On this phone only, not connected to a server': 'Chỉ trên điện thoại này, không kết nối với máy chủ',
