  'Sign out anyway': 'Vẫn đăng xuất',
  'Couldn’t keep a copy of the changes on this device. Nothing was removed.': 'Không thể lưu bản sao của các thay đổi trên thiết bị này. Chưa có dữ liệu nào bị xóa.',
  'Not everything is on your server yet': 'Chưa đồng bộ hết lên máy chủ của bạn',
