  'Try again, or export a backup first. Going ahead anyway keeps a copy of these changes on this device until it connects to this server as this account again. Then they’re added back.': 'Hãy thử lại, hoặc xuất bản sao lưu trước. Nếu vẫn tiếp tục, bản sao của các thay đổi này sẽ được giữ lại trên thiết bị cho đến khi kết nối lại với máy chủ bằng tài khoản này, sau đó chúng sẽ được đồng bộ lại.',
  'Syncing…': 'Đang đồng bộ…',
  'Try again': 'Thử lại',
  'Last synced: {0}': 'Đồng bộ lần cuối: {0}',
