  'Sync now': 'Đồng bộ ngay',
  'Your changes are kept here, and merged into your account once it is paired again.': 'Các thay đổi được lưu tại đây và sẽ được gộp vào tài khoản của bạn khi ghép đôi lại.',
  'Your changes are kept here, and merged into your account once you are signed in again.': 'Các thay đổi được lưu tại đây và sẽ được gộp vào tài khoản khi bạn đăng nhập lại.',
  'Changes kept for {0}': 'Các thay đổi được giữ lại cho {0}',
  'Added back when this device connects as that account again.': 'Sẽ được thêm lại khi thiết bị này kết nối lại với tài khoản đó.',
  'The changes your server has not seen are kept on this device, and added back when it connects as this account again.': 'Các thay đổi chưa có trên máy chủ sẽ được giữ trên thiết bị này và thêm lại khi kết nối lại bằng tài khoản này.',
  'This phone switches back to local-only and its copy of your account is removed. First it checks that your server has every change. If not, you choose what happens to them.': 'Điện thoại này sẽ chuyển về chế độ chỉ lưu cục bộ và bản sao tài khoản sẽ bị xóa. Trước tiên, ứng dụng sẽ kiểm tra xem máy chủ đã có đủ mọi thay đổi chưa. Nếu chưa, bạn có thể chọn cách xử lý.',
  'Your data is removed from this browser; your profile on the server keeps it. First it checks that the server has every change. If not, you choose what happens to them.': 'Dữ liệu của bạn sẽ bị xóa khỏi trình duyệt này; hồ sơ trên máy chủ vẫn sẽ lưu giữ. Trước tiên, ứng dụng sẽ kiểm tra xem máy chủ đã có đủ mọi thay đổi chưa. Nếu chưa, bạn có thể chọn cách xử lý.',
  'Signs this profile out on every device, including this one. Phones paired with it are disconnected and have to be paired again. Your passkeys keep working, so you can sign in with them again anytime.': 'Đăng xuất hồ sơ này khỏi mọi thiết bị, bao gồm cả thiết bị này. Các điện thoại đã ghép đôi sẽ bị ngắt kết nối và phải ghép đôi lại. Khóa truy cập (passkey) vẫn hoạt động nên bạn có thể dùng để đăng nhập lại bất cứ lúc nào.',
