  'This workout was deleted on another device. Your edits are still here.': 'Buổi tập này đã bị xóa trên thiết bị khác. Các chỉnh sửa của bạn vẫn còn ở đây.',
  'Close editor': 'Đóng trình chỉnh sửa',
  'Editing a saved workout. Date and duration stay unchanged.': 'Đang chỉnh sửa buổi tập đã lưu. Ngày và thời lượng sẽ giữ nguyên.',
  'A pull for every press, so the shoulders stay balanced.': 'Cứ một bài kéo tương ứng với một bài đẩy, giúp khớp vai luôn cân bằng.',
  'A two-day rotation across three sessions a week, built around the equipment you listed. Compounds first, one pull for every press, and enough overlap between the days that nothing goes two weeks without being trained.': 'Lịch xoay vòng 2 ngày chia đều cho 3 buổi tập một tuần, được thiết kế theo các thiết bị bạn có. Ưu tiên bài tập compound, cân đối một bài kéo cho mỗi bài đẩy, và các ngày tập xen kẽ hợp lý để không nhóm cơ nào bị bỏ trống quá hai tuần.',
  'Based on the training already in this demo profile.': 'Dựa trên dữ liệu tập luyện có sẵn trong hồ sơ demo này.',
  'Body weight has been flat for four weeks while the goal is to gain. That’s a kitchen problem, not a training one. The plan isn’t what’s holding it back.': 'Thể trọng không thay đổi trong bốn tuần dù mục tiêu là tăng cân. Đây là vấn đề dinh dưỡng chứ không phải do tập luyện. Kế hoạch tập không phải là lý do khiến bạn chững lại.',
  'Demo': 'Demo',
  'Demo data reset': 'Đặt lại dữ liệu demo',
  'Direct arm work, since you asked for it.': 'Tập tay chuyên biệt, đúng theo yêu cầu của bạn.',
  'Every top set on this one came in at RPE 9.5 or above for three sessions and the weight has not moved. Swapping the movement for four weeks usually breaks that stall faster than grinding the same one.': 'Mọi top set của bài này đều chạm ngưỡng RPE 9.5 trở lên trong ba buổi liên tiếp mà mức tạ vẫn giậm chân tại chỗ. Đổi sang bài tập khác trong bốn tuần thường giúp phá vỡ giai đoạn chững tạ này nhanh hơn là tiếp tục bám lấy bài cũ.',
  'Example data, stored only in this browser. Go wild and change anything you like.': 'Dữ liệu mẫu, chỉ lưu trên trình duyệt này. Cứ thoải mái thay đổi bất cứ thứ gì bạn muốn.',
  'Full body A': 'Toàn thân A',
  'Full body B': 'Toàn thân B',
  'Horizontal pressing, the other half of the session.': 'Bài đẩy ngang, nửa còn lại của buổi tập.',
  'Live demo. Everything stays in this browser.': 'Bản demo trực tiếp. Mọi thứ chỉ lưu trong trình duyệt này.',
  'No training history yet, so starting conservatively.': 'Chưa có lịch sử tập luyện, nên sẽ bắt đầu ở mức thận trọng.',
  'Passkey sign-in, sync across your devices, your own data.': 'Đăng nhập bằng Passkey, đồng bộ giữa các thiết bị, dữ liệu của riêng bạn.',
  'Puts the example plan, workouts and weigh-ins back the way they started.': 'Khôi phục lịch tập mẫu, các buổi tập và dữ liệu cân nặng về trạng thái ban đầu.',
  'Reset': 'Đặt lại',
  'Reset demo data': 'Đặt lại dữ liệu demo',
  'Reset demo data?': 'Đặt lại dữ liệu demo?',
  'Revised as you asked. Everything you did not question is exactly as it was.': 'Đã chỉnh sửa theo yêu cầu của bạn. Những phần bạn không đề cập vẫn được giữ nguyên.',
  'Same pattern, higher reps than day A.': 'Cùng dạng chuyển động, số reps cao hơn ngày A.',
  'Self-host it in a minute →': 'Tự host chỉ trong một phút →',
  'Self-host openGym': 'Tự host openGym',
  'Sessions have been running about fifteen minutes over. This is the accessory with the least to lose from one set fewer.': 'Các buổi tập đang bị kéo dài thêm khoảng 15 phút. Đây là bài bổ trợ ít ảnh hưởng nhất nếu giảm bớt một hiệp.',
  'Start the demo': 'Bắt đầu bản demo',
  'The main lower-body driver, where most of the strength comes from.': 'Bài tập thân dưới chủ lực, nơi tạo ra phần lớn sức mạnh.',
  'The same patterns, different variations: enough overlap to progress, enough difference to stay fresh.': 'Cùng dạng chuyển động, biến thể khác nhau: vừa đủ tương đồng để tiến bộ, vừa đủ khác biệt để không nhàm chán.',
  'The two big lower-body and pressing patterns first, while you are fresh.': 'Ưu tiên hai dạng bài lớn: thân dưới và bài đẩy trước, khi bạn còn sung sức.',
  'This demo runs entirely in your browser on example data. Nothing is sent anywhere. Passkey sign-in and sync across your devices come with the openGym server, which you get by self-hosting it.': 'Bản demo này chạy hoàn toàn trên trình duyệt của bạn với dữ liệu mẫu. Không có dữ liệu nào được gửi đi. Tính năng đăng nhập bằng Passkey và đồng bộ trên các thiết bị đi kèm với máy chủ openGym khi bạn tự host.',
  'Three things worth changing, and one worth knowing about. Everything else is working: the squat and the pulls are both progressing on schedule.': 'Ba điểm nên thay đổi, và một điểm cần lưu ý. Mọi thứ khác đều đang hiệu quả: squat và các bài kéo đều tiến bộ đúng kế hoạch.',
  'Vertical pressing.': 'Bài đẩy dọc.',
  'You have moved this session to Saturday three weeks running. Better the plan says so than that you keep overriding it.': 'Bạn đã chuyển buổi tập này sang thứ Bảy 3 tuần liên tiếp. Tốt hơn là cập nhật luôn vào lịch thay vì liên tục dời ngày thủ công.',
