  'Your server can’t be reached. Showing the last copy synced with it.': 'Không thể kết nối với máy chủ. Đang hiển thị bản sao được đồng bộ gần nhất.',
  'Server address unknown': 'Địa chỉ máy chủ không xác định',
  'Pair again, or export a backup first. Going ahead anyway keeps a copy of these changes on this device until it connects to this server as this account again. Then they’re added back.': 'Hãy ghép đôi lại hoặc xuất bản sao lưu trước. Nếu vẫn tiếp tục, bản sao của các thay đổi này sẽ được giữ lại trên thiết bị cho đến khi kết nối lại với máy chủ bằng tài khoản này, sau đó chúng sẽ được cập nhật lại.',
  'Sign in again, or export a backup first. Going ahead anyway keeps a copy of these changes on this device until it connects to this server as this account again. Then they’re added back.': 'Hãy đăng nhập lại hoặc xuất bản sao lưu trước. Nếu vẫn tiếp tục, bản sao của các thay đổi này sẽ được giữ lại trên thiết bị cho đến khi kết nối lại với máy chủ bằng tài khoản này, sau đó chúng sẽ được cập nhật lại.',
