  'The Coach couldn’t run. The instance owner needs to check its setup.': 'Huấn luyện viên không thể khởi chạy. Quản trị viên máy chủ cần kiểm tra lại cài đặt.',
  'The Coach answered with something the app couldn’t use.': 'Phản hồi từ Huấn luyện viên không thể xử lý được trên ứng dụng.',
  'The server restarted while the Coach was thinking.': 'Máy chủ đã khởi động lại trong khi Huấn luyện viên đang xử lý.',
  'The Coach couldn’t read your training data.': 'Huấn luyện viên không thể đọc dữ liệu tập luyện của bạn.',
  'The Coach is switched off on this instance for safety reasons.': 'Huấn luyện viên đã bị tắt trên máy chủ này vì lý do an toàn.',
