  'openGym can no longer write to the chosen folder, so copies go to Documents/openGym again. Choose the folder again to switch back.': 'openGym không thể ghi vào thư mục đã chọn nữa, nên các bản sao lưu sẽ quay về Documents/openGym. Hãy chọn lại thư mục nếu muốn chuyển về.',
  'Nudge me when I skip a planned workout': 'Nhắc nhở khi tôi bỏ lỡ buổi tập theo lịch',
