  'Friendly': 'Thân thiện',
  'Guilt trip': 'Gây áy náy',
  'Drill sergeant': 'Sĩ quan huấn luyện',
  'One nudge in the evening of a planned day with nothing logged, between 20:00 and 21:30. After 3 missed days in a row it goes quiet until your next workout.': 'Gửi một lượt nhắc vào buổi tối của ngày có lịch tập mà chưa ghi nhận buổi tập nào, trong khoảng 20:00 đến 21:30. Sau 3 ngày bỏ lỡ liên tiếp, ứng dụng sẽ tắt thông báo cho đến buổi tập tiếp theo của bạn.',
  'Everything okay?': 'Mọi thứ ổn chứ?',
