  'Rough day? {0} will keep. Tomorrow is a fresh start.': 'Một ngày vất vả sao? {0} vẫn sẽ đợi bạn. Ngày mai sẽ là khởi đầu mới.',
  'Hey, {0} didn’t happen today. All good?': 'Này, hôm nay không thấy bạn tập {0}. Mọi thứ vẫn ổn chứ?',
  'I miss you': 'Nhớ bạn quá',
  '{0} waited by the door all evening. For you.': '{0} đã đứng đợi ở cửa suốt cả buổi tối. Chỉ để chờ bạn.',
  'The barbell asked about you today. I didn’t know what to say.': 'Hôm nay thanh đòn cứ hỏi thăm bạn mãi. Tôi chẳng biết phải trả lời thế nào.',
  'Was it something I said? {0} misses you.': 'Có phải tôi đã lỡ lời gì không? {0} nhớ bạn đấy.',
  'I saved you a spot on the bench. It’s still empty.': 'Tôi đã giữ chỗ cho bạn trên ghế bench. Nó vẫn đang trống kìa.',
  'Attention, recruit!': 'Tân binh, chú ý!',
  'Your gains are packing their bags. {0} tomorrow, no excuses!': 'Cơ bắp của bạn đang dọn đồ ra đi đấy. Ngày mai tập {0}, không viện cớ!',
