  'Your muscles filed a missing-person report. Show up for {0}!': 'Cơ bắp của bạn đã nộp đơn báo mất tích rồi đấy. Xuất hiện ở buổi {0} ngay!',
  'That address answers, but it isn’t an openGym server. Check the URL.': 'Địa chỉ đó có phản hồi, nhưng không phải là máy chủ openGym. Hãy kiểm tra lại URL.',
  'That address answers, but a login page or proxy rule replied instead of openGym. Let /api/ through to openGym unchanged. See “Phone app and CORS” in docs/SELF_HOSTING.md.': 'Địa chỉ đó có phản hồi, nhưng trang đăng nhập hoặc quy tắc proxy đã phản hồi thay vì openGym. Hãy cho phép /api/ đi thẳng tới openGym mà không thay đổi. Xem “Phone app and CORS” trong docs/SELF_HOSTING.md.',
  'Switch sides': 'Đổi bên',
