  'Each exercise can have its own rest too. Set it in the exercise settings of a routine.': 'Mỗi bài tập cũng có thể có thời gian nghỉ riêng. Thiết lập trong cài đặt bài tập của lịch tập.',
  'iPhone doesn’t let openGym vibrate. A sound or a flash does the job.': 'iPhone không cho phép openGym rung. Thay vào đó, hãy dùng âm thanh hoặc đèn flash.',
  'No account, no cloud. Back it up anytime in Data & backup.': 'Không cần tài khoản, không dùng đám mây. Bạn có thể sao lưu bất cứ lúc nào trong Dữ liệu & sao lưu.',
  'Effort per set is off. Turn it on in Settings → Workout to keep rating.': 'Đánh giá nỗ lực mỗi hiệp đang tắt. Bật trong Cài đặt → Buổi tập để tiếp tục đánh giá.',
  'Enter the code your other device shows under Settings → Account → Add another device. This device then gets a passkey of its own.': 'Nhập mã hiển thị trên thiết bị kia tại Cài đặt → Tài khoản → Thêm thiết bị khác. Thiết bị này sau đó sẽ được cấp một mã khóa riêng.',
  'Open Settings → Account → “Pair the mobile app” on the openGym site you’re already signed into, then enter its address and the code shown there.': 'Mở Cài đặt → Tài khoản → “Ghép nối ứng dụng di động” trên trang openGym bạn đã đăng nhập, sau đó nhập địa chỉ trang và mã hiển thị ở đó.',
  'Open Settings → Account → “Pair the mobile app” on your openGym site in a browser and enter the new code shown there. What this phone kept is merged into your account.': 'Mở Cài đặt → Tài khoản → “Ghép nối ứng dụng di động” trên trang openGym trong trình duyệt và nhập mã mới hiển thị ở đó. Dữ liệu trên điện thoại này sẽ được gộp vào tài khoản của bạn.',
