  'Save as a backup file': 'Lưu dưới dạng tệp sao lưu',
  'Add this device\'s plan to your profile?': 'Thêm kế hoạch từ thiết bị này vào hồ sơ của bạn?',
  'Your plan, notes or gym cards on this device were set up while signed out. Add them to your profile, or keep the profile exactly as it is on the server.': 'Kế hoạch, ghi chú hoặc thẻ tập trên thiết bị này được tạo khi chưa đăng nhập. Thêm chúng vào hồ sơ của bạn, hoặc giữ nguyên hồ sơ hiện có trên máy chủ.',
  '{0} routine was made on this device while signed out. Add it to your profile, or keep the profile exactly as it is on the server.': '{0} lịch tập đã được tạo trên thiết bị này khi chưa đăng nhập. Thêm vào hồ sơ của bạn, hoặc giữ nguyên hồ sơ hiện có trên máy chủ.',
  '{0} routines were made on this device while signed out. Add them to your profile, or keep the profile exactly as it is on the server.': '{0} lịch tập đã được tạo trên thiết bị này khi chưa đăng nhập. Thêm vào hồ sơ của bạn, hoặc giữ nguyên hồ sơ hiện có trên máy chủ.',
