  'Greys show darker in light mode, so buttons don’t look switched off.': 'Màu xám hiển thị đậm hơn ở chế độ sáng để các nút không trông như bị vô hiệu hóa.',
  'custom color picker': 'bộ chọn màu tùy chỉnh',
  'Signed in from another tab. Your workout came along, keep going here.': 'Đã đăng nhập từ tab khác. Buổi tập của bạn đã được chuyển sang, hãy tiếp tục tại đây.',
  'Plain http:// isn’t encrypted. Fine on your home network, but use https:// if your server is reachable from the internet.': 'Giao thức http:// thông thường không được mã hóa. Bạn có thể dùng trong mạng nội bộ gia đình, nhưng hãy dùng https:// nếu máy chủ kết nối qua internet.',
  'Could not reach {0} over https://. If your server runs on plain http (common at home), type http://{0} instead.': 'Không thể kết nối với {0} qua https://. Nếu máy chủ của bạn chạy http thông thường (phổ biến ở mạng gia đình), hãy nhập http://{0} thay thế.',
