  '{0} photo knows its day and goes there. The others go on the day below.': '{0} ảnh biết ngày chụp và sẽ vào đúng ngày đó. Các ảnh khác vào ngày bên dưới.',
  '{0} photos know their day and go there. The others go on the day below.': '{0} ảnh biết ngày chụp và sẽ vào đúng ngày đó. Các ảnh khác vào ngày bên dưới.',
  'Every progress photo, lined up by date, for any day. Plus a before/after slider.': 'Mọi ảnh tiến độ, xếp theo ngày, cho bất kỳ ngày nào. Kèm thanh trượt trước/sau.',
