  'Backups': 'Bản sao lưu',
  'Backups for {0}': 'Bản sao lưu cho {0}',
  'Everything else': 'Mọi thứ khác',
  'Machine taken? Pick what you’d do instead, and a swap mid-workout offers these first.': 'Máy đang có người dùng? Chọn bài bạn sẽ tập thay, và khi đổi bài giữa buổi tập, các bài này sẽ được gợi ý trước.',
  'Remove “{0}”': 'Xóa “{0}”',
  "Rename “{0}”": "Đổi tên “{0}”",
  'That’s plenty of backups.': 'Vậy là đủ bài dự phòng rồi.',
  'Your backups': 'Bài dự phòng của bạn',
  'Swap to {0}': 'Đổi sang {0}',
  'Planned backup, same sets and reps': 'Bài dự phòng đã lên kế hoạch, cùng hiệp và reps',
  'Planned backup, with its own plan': 'Bài dự phòng đã lên kế hoạch, có kế hoạch riêng',
  'Same plan as this exercise. Tap to give it its own.': 'Cùng kế hoạch với bài tập này. Chạm để cho nó kế hoạch riêng.',
  'Nothing to add in weight here: it goes up in reps, then sets.': 'Ở đây không có tạ để thêm: bài này tăng reps trước, rồi tăng hiệp.',
  'In Cards and Focus, Prev and Next hop over a finished exercise.': 'Ở chế độ Thẻ và Tập trung, Trước và Tiếp sẽ nhảy qua bài tập đã xong.',
  'Skip completed exercises': 'Bỏ qua bài tập đã hoàn thành',
  'This app can’t confirm with a passkey. Make the code in a browser signed in to this profile, or add a password there first.': 'Ứng dụng này không xác nhận được bằng passkey. Hãy tạo mã trong trình duyệt đã đăng nhập hồ sơ này, hoặc đặt mật khẩu ở đó trước.',
  'Apple Watch': 'Apple Watch',
  'Weight': 'Mức tạ',
  'Send workouts to the watch': 'Gửi buổi tập sang đồng hồ',
  'Open on the watch': 'Mở trên đồng hồ',
  'Start a workout on the phone and openGym pops up on your wrist.': 'Bắt đầu buổi tập trên điện thoại và openGym hiện ngay trên cổ tay bạn.',
  'Not allowed': 'Không được phép',
  'Turn on Apple Health and the watch measures your heart rate for every set.': 'Bật Apple Health và đồng hồ sẽ đo nhịp tim cho từng hiệp.',
  'Tap the wrist when a rest is over': 'Rung cổ tay khi hết giờ nghỉ',
  'No Apple Watch paired with this iPhone': 'Chưa có Apple Watch nào ghép nối với iPhone này',
  'openGym is not on your Apple Watch yet. Install it in the Watch app.': 'openGym chưa có trên Apple Watch của bạn. Hãy cài trong ứng dụng Watch.',
