  'Not allowed on the watch. Allow it in the Health app on your iPhone.': 'Chưa được phép trên đồng hồ. Hãy cho phép trong ứng dụng Sức khỏe trên iPhone.',
  'Heart rate during the workout and next to each set, and the workout saved to Apple Health. The watch asks once.': 'Nhịp tim trong buổi tập và bên cạnh từng hiệp, buổi tập được lưu vào Apple Health. Đồng hồ chỉ hỏi một lần.',
  'Apple Health': 'Apple Health',
  'Write to Apple Health': 'Ghi vào Apple Health',
  'Open Apple Health': 'Mở Apple Health',
  'Workouts and weigh-ins go to Apple Health when you finish or change them.': 'Buổi tập và lần cân được ghi vào Apple Health khi bạn hoàn thành hoặc chỉnh sửa chúng.',
  'Writing to Apple Health': 'Đang ghi vào Apple Health',
  'Apple Health permission not granted': 'Chưa được cấp quyền Apple Health',
