  'Stop writing to Apple Health?': 'Ngừng ghi vào Apple Health?',
  'What openGym already wrote can stay in Apple Health as your data, or be removed from it.': 'Những gì openGym đã ghi có thể ở lại trong Apple Health như dữ liệu của bạn, hoặc bị xóa đi.',
  'Your workouts in Apple Health': 'Buổi tập của bạn trong Apple Health',
  'openGym can save every workout and weigh-in to Apple Health, and your Apple Watch can show your heart rate while you lift.': 'openGym có thể lưu mọi buổi tập và lần cân vào Apple Health, và Apple Watch có thể hiện nhịp tim khi bạn nâng tạ.',
  'Workouts and weigh-ins saved to Apple Health': 'Buổi tập và lần cân được lưu vào Apple Health',
  'Heart rate per set on your Apple Watch': 'Nhịp tim từng hiệp trên Apple Watch',
