  'Your bar for this type, set in Your bars.': 'Thanh đòn của bạn cho loại này, đặt trong Thanh đòn của bạn.',
  'What the bars at your gym weigh. Every exercise with that bar counts plates from it, unless you gave the exercise its own. Logged weights stay totals.': 'Thanh đòn ở phòng tập của bạn nặng bao nhiêu. Mọi bài tập dùng thanh đó sẽ tính bánh tạ từ mức này, trừ khi bạn đặt riêng cho bài tập. Mức tạ đã ghi vẫn là tổng.',
  'Most lifts in the library use “{0}”, a few use “{1}”. A short bar for all of them means setting both.': 'Phần lớn bài tập trong thư viện dùng “{0}”, một số ít dùng “{1}”. Muốn dùng thanh ngắn cho tất cả thì phải đặt cả hai.',
