  'An exercise’s history, records and progress are worked out from your workouts. Fix the workout and they follow.': 'Lịch sử, kỷ lục và tiến độ của bài tập được tính từ các buổi tập. Sửa buổi tập là chúng tự cập nhật theo.',
  'Back home, practice over. Stats is where the gains pile up. Tap it.': 'Về nhà rồi, buổi tập thử đã xong. Thống kê là nơi thành quả chất đống. Chạm vào đó.',
