  'Up next: {0}, starts by itself': 'Tiếp theo: {0}, tự bắt đầu',
  'When the rest ends: 3, 2, 1 and the hold starts. Pause, restart or stop it any time.': 'Khi hết giờ nghỉ: 3, 2, 1 và tư thế giữ bắt đầu. Tạm dừng, bắt đầu lại hoặc dừng bất cứ lúc nào.',
  'Holds start by themselves': 'Tư thế giữ tự bắt đầu',
  'Add {0}?': 'Thêm {0}?',
  'Any blank NTAG sticker works. Writing replaces what was on it.': 'Sticker NTAG trống nào cũng được. Ghi sẽ thay thế nội dung cũ trên đó.',
  'Hold the back of your phone to the sticker.': 'Áp mặt lưng điện thoại vào sticker.',
  'Hold the top of your iPhone near the sticker.': 'Đưa phần trên iPhone lại gần sticker.',
  'It isn’t in this workout yet.': 'Bài này chưa có trong buổi tập.',
  'Just check in': 'Chỉ check-in',
  'NFC is off. Turn it on in your phone’s settings and try again.': 'NFC đang tắt. Hãy bật trong cài đặt của điện thoại rồi thử lại.',
  'NFC sticker for this exercise': 'Sticker NFC cho bài tập này',
  'Put it on your locker, your bag or the gym door. One tap with your phone and you’re in.': 'Dán lên tủ đồ, túi hoặc cửa phòng tập. Chạm điện thoại một cái là vào.',
  'Set up an NFC sticker': 'Thiết lập sticker NFC',
  'Shows your gym membership code, ready for the scanner.': 'Hiện mã thẻ hội viên phòng tập, sẵn sàng cho máy quét.',
  'Start today’s workout': 'Bắt đầu buổi tập hôm nay',
  'Starts what’s planned for today, or opens the one already running.': 'Bắt đầu buổi đã lên kế hoạch cho hôm nay, hoặc mở buổi đang chạy.',
  'Stick it on the machine. Tap it during a workout to jump to {0}, or to add it.': 'Dán lên máy tập. Chạm vào nó trong buổi tập để nhảy tới {0}, hoặc để thêm bài đó.',
  'Sticker ready.': 'Sticker đã sẵn sàng.',
  'Sticker ready. Tap it with your phone to try it.': 'Sticker đã sẵn sàng. Chạm điện thoại vào để thử.',
  'Tap it at the gym to start your workout or show your code.': 'Chạm vào nó ở phòng tập để bắt đầu buổi tập hoặc hiện mã của bạn.',
  'That didn’t work. Hold your phone still on the sticker and try again.': 'Không được rồi. Giữ yên điện thoại trên sticker và thử lại.',
  'This sticker can’t hold a link. Try an NTAG sticker.': 'Sticker này không chứa được liên kết. Hãy thử sticker NTAG.',
  'This sticker is for an exercise you don’t have.': 'Sticker này dành cho một bài tập bạn không có.',
  'This sticker is locked. Try a blank one.': 'Sticker này đã bị khóa. Hãy thử sticker trống.',
  'This sticker is too small. NTAG213 or bigger works.': 'Sticker này quá nhỏ. Dùng NTAG213 trở lên.',
  'When you tap it': 'Khi bạn chạm vào',
  'Which code': 'Mã nào',
  'Write NFC sticker for this exercise': 'Ghi sticker NFC cho bài tập này',
  'Write sticker': 'Ghi sticker',
  'openGym isn’t allowed to use NFC here.': 'openGym không được phép dùng NFC ở đây.',
  '“{0}” added': 'Đã thêm “{0}”',
  'And beside it': 'Và bên cạnh',
  'Best: {0}': 'Tốt nhất: {0}',
  'Every badge collected. Legend.': 'Đã sưu tầm đủ mọi huy hiệu. Huyền thoại.',
  'Freezes full. A missed week uses one, no harm done.': 'Đã đầy lượt đóng băng. Bỏ lỡ một tuần sẽ dùng một lượt, không sao cả.',
  'Goal reached': 'Đã đạt mục tiêu',
  'Last week: {0}': 'Tuần trước: {0}',
