  'No goal set': 'Chưa đặt mục tiêu',
  'No weigh-ins yet': 'Chưa có lần cân nào',
  'Nothing planned': 'Chưa lên kế hoạch gì',
  'Streak badges': 'Huy hiệu chuỗi',
  'Streak freezes': 'Lượt đóng băng chuỗi',
  'Streak freezes: {0} of {1}': 'Lượt đóng băng chuỗi: {0} / {1}',
  'Week done. The flame lives on.': 'Xong tuần. Ngọn lửa vẫn cháy.',
  'Weight goal': 'Mục tiêu thể trọng',
  'What to show': 'Hiển thị gì',
  '{0} vs last week': '{0} so với tuần trước',
  '{0} weeks in a row. New badge!': '{0} tuần liên tiếp. Huy hiệu mới!',
  '{0} weeks: not yet': '{0} tuần: chưa đạt',
  '{0} weeks: reached': '{0} tuần: đã đạt',
  '{0} PR this month': '{0} PR tháng này',
  '{0} PRs this month': '{0} PR tháng này',
  'One more week with a workout earns a freeze.': 'Thêm một tuần có tập nữa là được một lượt đóng băng.',
  '{0} more weeks with a workout earn a freeze.': 'Thêm {0} tuần có tập nữa là được một lượt đóng băng.',
  'Watch on YouTube': 'Xem trên YouTube',
  'Opens a search for good form': 'Mở tìm kiếm về kỹ thuật đúng',
  'Share with a friend': 'Chia sẻ với bạn bè',
  'As a routine they can do too': 'Dưới dạng lịch tập để họ cũng tập được',
  'Nothing to share in this one.': 'Buổi này không có gì để chia sẻ.',
  'Link copied. Paste it to a friend.': 'Đã sao chép liên kết. Dán gửi cho bạn bè nhé.',
  'That one’s too big for a link, so it goes as a plan file.': 'Cái này quá lớn để làm liên kết, nên sẽ gửi dạng tệp kế hoạch.',
  'Here’s my {0} on openGym 💪': 'Đây là {0} của mình trên openGym 💪',
  'Couldn’t make a link for this one.': 'Không tạo được liên kết cho cái này.',
  'A link to “{0}”. Your friend taps it and adds it to their own openGym. The routine rides inside the link, no server in between.': 'Một liên kết tới “{0}”. Bạn của bạn chạm vào và thêm nó vào openGym của họ. Lịch tập nằm ngay trong liên kết, không có máy chủ ở giữa.',
  'Include my weights': 'Kèm mức tạ của tôi',
  'Off: just sets, reps and rest. They pick their own weights.': 'Tắt: chỉ có hiệp, reps và thời gian nghỉ. Họ tự chọn mức tạ.',
  'So they know who it’s from.': 'Để họ biết ai gửi.',
  'Share link': 'Chia sẻ liên kết',
  'From {0}': 'Từ {0}',
  'Added as a new routine. Nothing you already have is touched.': 'Đã thêm thành lịch tập mới. Những gì bạn đang có không bị đụng tới.',
  'Add to my routines': 'Thêm vào lịch tập của tôi',
  'Added to your routines': 'Đã thêm vào lịch tập của bạn',
  'This link is from a newer openGym. Update the app to open it.': 'Liên kết này từ phiên bản openGym mới hơn. Hãy cập nhật ứng dụng để mở.',
  'This browser can’t open this link. Try it in the openGym app.': 'Trình duyệt này không mở được liên kết này. Hãy thử trong ứng dụng openGym.',
  'Nothing in this routine works here, sorry.': 'Rất tiếc, không có gì trong lịch tập này dùng được ở đây.',
  'This routine link is broken or cut off.': 'Liên kết lịch tập này bị hỏng hoặc bị cắt mất.',
  '(from {0})': '(từ {0})',
  'Mostly in the morning. The early bird gets the barbell.': 'Chủ yếu vào buổi sáng. Chim dậy sớm thì được thanh đòn.',
  'Mostly around lunch. Who needs a lunch break anyway?': 'Chủ yếu vào giờ trưa. Ai cần nghỉ trưa chứ?',
