  'Every challenge you finish puts a badge here, one shelf per month.': 'Mỗi thử thách bạn hoàn thành sẽ đặt một huy hiệu ở đây, mỗi tháng một kệ.',
  'Monthly challenges': 'Thử thách hàng tháng',
  'Three goals a month on Home, sized to how you train.': 'Ba mục tiêu mỗi tháng ở Trang chủ, vừa với cách bạn tập.',
  'Plain http:// only works for an address on your home network, like 192.168.x.x, a .local name or a Tailscale 100.x address. Anything on the internet needs https://.': 'http:// thường chỉ dùng được cho địa chỉ trong mạng nhà bạn, như 192.168.x.x, tên .local hoặc địa chỉ Tailscale 100.x. Mọi thứ trên internet cần https://.',
  'Plain http only on your home network': 'http thường chỉ trong mạng nhà bạn',
  'Freestyle repeats what you did last time, with no progression rule. Rules apply to exercises in a routine.': 'Tập tự do lặp lại những gì bạn làm lần trước, không có quy tắc tăng tiến. Quy tắc áp dụng cho bài tập trong lịch tập.',
  'Your watch thought this workout was forgotten. It keeps going here.': 'Đồng hồ của bạn tưởng buổi tập này bị bỏ quên. Nó vẫn tiếp tục ở đây.',
  'No rule (freestyle)': 'Không quy tắc (tự do)',
  'Freestyle keeps the numbers you set. A rule picked here applies to this workout only.': 'Tập tự do giữ các con số bạn đặt. Quy tắc chọn ở đây chỉ áp dụng cho buổi tập này.',
