  'Body': 'Cơ thể',
  'Built from your work weight and rounded to this gym’s plates and dumbbells. An exercise can pick its own in its settings.': 'Được tạo từ mức tạ chính và làm tròn theo bánh tạ, tạ đơn của phòng tập này. Mỗi bài tập có thể tự chọn trong cài đặt của nó.',
  'Built from your work weight when the workout starts.': 'Được tạo từ mức tạ chính khi buổi tập bắt đầu.',
