  'Each one closes half the gap to the work weight.': 'Mỗi hiệp thu hẹp một nửa khoảng cách tới mức tạ chính.',
  'Every loaded lift': 'Mọi bài có tải tạ',
  'Feeling great': 'Đang thấy rất khỏe',
