  'For this workout': 'Cho buổi tập này',
  'Heavy lifts get more rungs, light ones one or none.': 'Bài nặng có nhiều bậc hơn, bài nhẹ một bậc hoặc không có.',
  'It hurts': 'Bị đau',
  'It hurts, it’s taken, no time, feeling great': 'Bị đau, máy có người, không có thời gian, đang thấy rất khỏe',
  'It pinches, so lighter for the rest of it. Stop if it still hurts.': 'Hơi nhói, nên phần còn lại tập nhẹ hơn. Dừng lại nếu vẫn đau.',
  'It pinches, so the sets you have left go to a movement that loads the same muscle from a kinder angle.': 'Hơi nhói, nên các hiệp còn lại chuyển sang một động tác tác động cùng nhóm cơ từ góc nhẹ nhàng hơn.',
  'Keep these warm-ups': 'Giữ các hiệp khởi động này',
  'Kept. Same warm-ups next time, scaled to your work weight.': 'Đã giữ. Lần sau vẫn các hiệp khởi động này, điều chỉnh theo mức tạ chính.',
  'Logged sets and your routine stay as they are. The Coach is not a doctor or a physiotherapist. If something hurts, ask a professional.': 'Các hiệp đã ghi và lịch tập của bạn giữ nguyên. Coach không phải bác sĩ hay chuyên gia vật lý trị liệu. Nếu có chỗ nào đau, hãy hỏi người có chuyên môn.',
  'Looking at your workout…': 'Đang xem buổi tập của bạn…',
  'Machine’s taken': 'Máy có người dùng',
  'My own': 'Của riêng tôi',
  'New programme “{0}”': 'Chương trình mới “{0}”',
  'Nothing at {0} {1}: that one starts cold.': 'Không khởi động ở mức {0} {1}: bài đó vào thẳng hiệp chính.',
  'Nothing could be applied any more.': 'Không còn áp dụng được gì nữa.',
  'Nothing to change. Carry on as planned.': 'Không cần thay đổi gì. Cứ tập theo kế hoạch.',
  'One set less keeps the session doable today and still counts.': 'Bớt một hiệp giúp buổi tập hôm nay vẫn vừa sức và vẫn được tính.',
  'Only the warm-ups you plan yourself.': 'Chỉ các hiệp khởi động bạn tự lên kế hoạch.',
  'Ramped from the work weight: more rungs when it is heavy, fewer when it is light.': 'Tăng dần từ mức tạ chính: nhiều bậc hơn khi nặng, ít hơn khi nhẹ.',
  'Remove warm-up {0}': 'Xóa hiệp khởi động {0}',
  'Revise programme “{0}”': 'Chỉnh sửa chương trình “{0}”',
  'Routines, exercises, sets and reps, warm-ups, programmes, your weekly schedule, progression settings and what your gym can load.': 'Lịch tập, bài tập, hiệp và reps, khởi động, chương trình, lịch tuần, cài đặt tăng tiến và những gì phòng tập của bạn có thể tải.',
  'Running on empty': 'Cạn năng lượng',
  'Saved in the routine, scaled to your work weight': 'Lưu trong lịch tập, điều chỉnh theo mức tạ chính',
  'Saved under Plan → Programmes. It starts when you start it.': 'Đã lưu trong Kế hoạch → Chương trình. Nó bắt đầu khi bạn bắt đầu.',
  'Short on time': 'Không có nhiều thời gian',
  'Skip the rest of {0}': 'Bỏ qua phần còn lại của {0}',
  'Something else': 'Chuyện khác',
  'Squats, presses, rows and friends get a ramp. Curls and raises start cold.': 'Squat, đẩy, kéo và các bài tương tự có hiệp tăng dần. Curl và nâng tạ ngang vào thẳng, không khởi động.',
  'Straight into the work sets.': 'Vào thẳng hiệp chính.',
  'That workout is over, so these can’t be applied any more.': 'Buổi tập đó đã kết thúc, nên không áp dụng được các thay đổi này nữa.',
  'The app ramps up from your work weight: more warm-up sets when it is heavy, fewer when it is light, on your gym’s plates.': 'Ứng dụng tăng dần từ mức tạ chính: nhiều hiệp khởi động hơn khi nặng, ít hơn khi nhẹ, theo bánh tạ của phòng tập.',
  'The rack is taken, so do it at the end. The rest of the session does not need it.': 'Giá đỡ đang có người, nên tập bài đó cuối buổi. Phần còn lại của buổi tập không cần đến nó.',
  'There’s no workout running.': 'Không có buổi tập nào đang chạy.',
  'These warm-ups come before the work sets every session, as a share of the work weight, so they grow with it.': 'Các hiệp khởi động này đi trước hiệp chính ở mọi buổi tập, theo tỉ lệ mức tạ chính, nên tăng theo nó.',
  'This is the demo, so there is no AI model behind me. On your own server I read your session and suggest changes like these.': 'Đây là bản demo, nên không có mô hình AI nào phía sau tôi. Trên máy chủ của riêng bạn, tôi đọc buổi tập của bạn và gợi ý những thay đổi như thế này.',
  'Warm-up {0}': 'Khởi động {0}',
  'Warm-ups': 'Khởi động',
  'What’s up? The Coach suggests a few changes to what is left of this workout. Logged sets stay as they are.': 'Có chuyện gì vậy? Coach gợi ý vài thay đổi cho phần còn lại của buổi tập. Các hiệp đã ghi giữ nguyên.',
