  "Your streak wears a Santa hat, all year if you like. Change it any time in Settings, Icons.": "Chuỗi ngày của bạn đội mũ ông già Noel, cả năm cũng được. Đổi bất cứ lúc nào ở Cài đặt, Biểu tượng.",
  "{0}% of all the work you did. Clearly a favourite.": "{0}% tổng sức bạn đã bỏ ra. Rõ ràng là món yêu thích.",
