  "Carry the shopping like it owes you money. Tall chest, slow steps.": "Xách đồ đi chợ như thể nó nợ bạn tiền. Ngực thẳng, bước chậm.",
  "You found Rudolph! He says hi and hides again. New spot tomorrow.": "Bạn tìm thấy Rudolph rồi! Cậu ấy chào một tiếng rồi lại trốn. Mai có chỗ mới.",
