  "Open this day": "Mở ngày này",
  "Planned, not trained. Any other day this week still counts.": "Đã lên lịch, chưa tập. Bất kỳ ngày nào khác trong tuần này vẫn được tính.",
  "Planned, not trained. Any workout that week would have counted.": "Đã lên lịch, chưa tập. Tập bất kỳ buổi nào trong tuần đó cũng sẽ được tính.",
  "Planned, not trained. No harm done: you trained another day that week, so it still counts.": "Đã lên lịch, chưa tập. Không sao: bạn đã tập vào ngày khác, nên tuần đó vẫn được tính.",
  "Bank 1 freeze, earned every 4 trained weeks. Two missed weeks in a row end the streak.": "Giữ 1 lượt đóng băng, cứ 4 tuần tập được một lượt. Lỡ hai tuần liên tiếp là chuỗi kết thúc.",
  "Bank up to 2 freezes, one every 4 trained weeks. Even two missed weeks in a row can be covered.": "Giữ tối đa 2 lượt đóng băng, cứ 4 tuần tập được một lượt. Lỡ cả hai tuần liên tiếp cũng có thể được giữ.",
  "Change the freeze rule": "Đổi quy tắc đóng băng",
  "Every 4th week you train earns a freeze. You can bank 1.": "Cứ mỗi tuần tập thứ 4 bạn được một lượt đóng băng. Có thể giữ 1 lượt.",
  "Every week counts. Miss one and the streak starts over.": "Tuần nào cũng tính. Lỡ một tuần là chuỗi bắt đầu lại.",
  "From now on: {0}.": "Từ giờ: {0}.",
  "From the week of {0} on: {1}.": "Từ tuần {0}: {1}.",
  "Generous": "Rộng rãi",
  "Gentle": "Nhẹ nhàng",
  "How forgiving should your week streak be?": "Chuỗi tuần của bạn nên dễ tính đến mức nào?",
  "How strict should your streak be?": "Chuỗi của bạn nên nghiêm đến mức nào?",
  "Miss a week and a freeze covers it: the streak keeps going, that week just adds nothing. Two missed weeks in a row, and it starts over.": "Lỡ một tuần? Một lượt đóng băng sẽ giữ nó: chuỗi vẫn tiếp tục, tuần đó chỉ không cộng thêm. Lỡ hai tuần liên tiếp thì chuỗi bắt đầu lại.",
  "No freezes": "Không đóng băng",
  "No freezes on your rule. Every week counts.": "Quy tắc của bạn không có lượt đóng băng. Tuần nào cũng tính.",
  "No freezes on your rule: a week without a workout starts it over.": "Quy tắc của bạn không có lượt đóng băng: một tuần không tập là chuỗi bắt đầu lại.",
  "No workout, and your rule has no freezes, so the streak started over.": "Không tập, và quy tắc của bạn không có lượt đóng băng, nên chuỗi bắt đầu lại.",
  "Weeks already counted stay as they are.": "Các tuần đã tính vẫn giữ nguyên.",
  "You can change it later in Settings. A change counts from then on.": "Bạn có thể đổi sau trong Cài đặt. Thay đổi có hiệu lực từ lúc đó.",
  "Your rule right now: {0}.": "Quy tắc hiện tại: {0}.",
  "Your streak counts weeks with at least one workout. Freezes can cover the odd missed week.": "Chuỗi đếm số tuần có ít nhất một buổi tập. Lượt đóng băng có thể giữ một tuần thỉnh thoảng bị lỡ.",
