  "You are letting this trainer see the categories marked here, and change the ones marked suggest or apply. If the trainer works for a gym, its gym lead sees the categories in the gym lead row, never more than view. You can change this or disconnect any time, and it stops working the moment you do. Every look and every change is written to your sharing log, which only you can read.": "Bạn đang cho huấn luyện viên này xem các hạng mục được đánh dấu ở đây, và sửa những hạng mục được đánh dấu là gợi ý hoặc sửa trực tiếp. Nếu huấn luyện viên làm việc cho một phòng gym, quản lý phòng gym đó xem được các hạng mục ở hàng quản lý phòng gym, và không bao giờ nhiều hơn quyền xem. Bạn có thể đổi điều này hoặc ngắt kết nối bất cứ lúc nào, và nó ngừng hoạt động ngay khi bạn làm vậy. Mọi lượt xem và mọi thay đổi đều được ghi vào nhật ký chia sẻ của bạn, và chỉ mình bạn đọc được.",
