  "Keep training together privately? Your sharing stays as it is, without the gym lead. Until {0}, then it ends by itself.": "Tiếp tục tập cùng nhau một cách riêng tư? Việc chia sẻ giữ nguyên như hiện tại, không còn quản lý phòng gym. Đến {0}, rồi tự kết thúc.",
