  "The sharing text changed. Have a quick read and try again.": "Văn bản chia sẻ đã thay đổi. Đọc nhanh qua rồi thử lại nhé.",
  "This is public to everyone on this server: everyone with an account here can see it, try it and copy it. Your name and the date go with it, always. Only share what is yours: something you made, recorded or have the right to pass on. The exercise pictures and animations of the built-in library are licensed and can never be shared. You can stop sharing any time; copies people already took stay with them.": "Nội dung này công khai với mọi người trên máy chủ này: bất kỳ ai có tài khoản ở đây đều có thể xem, thử và sao chép. Tên của bạn và ngày chia sẻ luôn đi kèm. Chỉ chia sẻ những gì là của bạn: thứ bạn tự làm, tự ghi lại hoặc có quyền chuyển tiếp. Hình ảnh và hoạt ảnh bài tập trong thư viện có sẵn có bản quyền và không bao giờ được chia sẻ. Bạn có thể ngừng chia sẻ bất cứ lúc nào; các bản sao người khác đã lấy vẫn ở lại với họ.",
  "This kind of item cannot be taken.": "Loại mục này không thể lấy được.",
