  "Download": "Tải xuống",
  "Changed your mind? Settings has it, any time.": "\u0110\u1ed5i \u00fd? C\u00f3 trong C\u00e0i \u0111\u1eb7t, b\u1ea5t c\u1ee9 l\u00fac n\u00e0o.",
  "A profile here already uses that e-mail. Sign in to it another way, then link {0} in Settings.": "Đã có một hồ sơ ở đây dùng email đó. Hãy đăng nhập vào hồ sơ đó bằng cách khác, rồi liên kết {0} trong Cài đặt.",
