  "That sign-in took too long or came from another tab. Give it another go.": "Lần đăng nhập đó quá lâu hoặc đến từ thẻ khác. Thử lại nhé.",
  "That was a different {0} account than the one linked to this profile.": "Đó là một tài khoản {0} khác với tài khoản đã liên kết với hồ sơ này.",
  "That {0} account is already linked to another profile here.": "Tài khoản {0} đó đã liên kết với một hồ sơ khác ở đây.",
  "This profile is already linked to a {0} account.": "Hồ sơ này đã liên kết với một tài khoản {0}.",
  "This profile is linked to your {0} account, so signing in there signs you in here.": "Hồ sơ này liên kết với tài khoản {0} của bạn: đăng nhập ở đó là đăng nhập ở đây.",
  "This server is invite-only and {0} alone does not get you in. Ask whoever runs it.": "Máy chủ này chỉ dành cho người được mời và chỉ {0} thôi thì chưa đủ. Hãy hỏi người quản lý.",
  "This server signs everyone in with {0}. New here? Signing in makes your profile.": "Trên máy chủ này mọi người đăng nhập bằng {0}. Mới đến? Đăng nhập sẽ tạo hồ sơ của bạn.",
  "This server signs people in with {0}.": "Máy chủ này cho mọi người đăng nhập bằng {0}.",
  "Too many attempts. Try again in a minute.": "Quá nhiều lần thử. Thử lại sau một phút.",
  "Unlink": "Hủy liên kết",
  "Unlinked. {0} no longer signs you in here.": "Đã hủy liên kết. {0} không còn đăng nhập cho bạn ở đây.",
  "or use a pairing code": "hoặc dùng mã ghép nối",
  "{0} could not be reached. Try again in a moment.": "Không liên lạc được với {0}. Thử lại sau giây lát.",
  "{0} is the only way into this profile, so it stays linked. Add a passkey first.": "{0} là cách duy nhất để vào hồ sơ này, nên vẫn giữ liên kết. Hãy thêm một passkey trước.",
  "{0} let you in, but this server only takes certain groups. Ask whoever runs it to add you.": "{0} đã cho bạn vào, nhưng máy chủ này chỉ nhận một số nhóm. Hãy nhờ người quản lý thêm bạn vào.",
  "{0} sent back something we could not verify, so nobody was signed in. If it keeps happening, the admin page shows why.": "{0} gửi lại thứ mà chúng tôi không xác minh được, nên không ai được đăng nhập. Nếu lặp lại, trang quản trị sẽ cho biết lý do.",
