  "Same brand at another gym? It shares these numbers. Records and Stats still count every gym.": "Cùng hãng ở phòng tập khác? Nó dùng chung các số này. Kỷ lục và Thống kê vẫn tính mọi phòng tập.",
  "For machines and cables that feel different from gym to gym. Free weights rarely need it.": "Dành cho máy và cáp mỗi phòng tập một cảm giác. Tạ tự do hiếm khi cần.",
  "All gyms": "Mọi phòng tập",
  "Today’s planned rows for {0} didn’t fit, so the routine’s own are up: {1}": "Các hiệp đã lên kế hoạch cho {0} không khớp, nên dùng hiệp của bài tập: {1}",
  "Today’s rows come from {0}. Your routine stays as it is.": "Các hiệp hôm nay do {0} đặt. Bài tập của bạn vẫn giữ nguyên.",
  "Today’s rows were planned for this day. Your routine stays as it is.": "Các hiệp hôm nay được lên kế hoạch cho ngày này. Bài tập của bạn vẫn giữ nguyên.",
