  "Body fat and lean mass, as your scale saved them. Shown under Body measurements, never mixed into what you log.": "Mỡ cơ thể và khối nạc, đúng như cân của bạn đã lưu. Hiện ở Số đo cơ thể, không bao giờ lẫn vào những gì bạn ghi.",
  "Body fat, lean mass, bone mass, body water and BMR, as your scale saved them. Shown under Body measurements, never mixed into what you log.": "Mỡ cơ thể, khối nạc, khối lượng xương, nước trong cơ thể và BMR, đúng như cân của bạn đã lưu. Hiện ở Số đo cơ thể, không bao giờ lẫn vào những gì bạn ghi.",
