  "A buzz for each phase": "Rung riêng cho từng pha",
  "A copy of everything, once a day, in a folder of your own: Nextcloud, ownCloud, a NAS, anything that speaks WebDAV. Your server, nobody else’s.": "Một bản sao của mọi thứ, mỗi ngày một lần, trong thư mục của riêng bạn: Nextcloud, ownCloud, NAS, bất cứ thứ gì nói được WebDAV. Máy chủ của bạn, không phải của ai khác.",
  "A sound for each kind of rest": "Âm thanh riêng cho từng kiểu nghỉ",
  "A tick on every day you trained, with how many sets. Only you see it, the same as the plan.": "Một dấu tích cho mỗi ngày bạn tập, kèm số hiệp. Chỉ bạn thấy, giống như kế hoạch.",
