  "Calendar feed": "Nguồn lịch",
  "Calendar feed off": "Đã tắt nguồn lịch",
  "Cardio goes up as what it was: a run, a ride, a row. Strength as Weight Training, with every set in the description.": "Cardio được tải lên đúng như nó là: chạy, đạp xe, chèo. Bài sức mạnh thành Tập tạ, mọi hiệp đều ghi trong phần mô tả.",
  "Change server or password": "Đổi máy chủ hoặc mật khẩu",
  "Check the connection": "Kiểm tra kết nối",
  "Connect Strava once from openGym in a browser, signed in to your server. Your workouts then go up from the server, whichever device you log them on.": "Kết nối Strava một lần từ openGym trên trình duyệt, khi đã đăng nhập vào máy chủ của bạn. Sau đó buổi tập sẽ được tải lên từ máy chủ, dù bạn ghi trên thiết bị nào.",
  "Connected. Your first backup goes up now.": "Đã kết nối. Bản sao lưu đầu tiên đang được tải lên.",
  "Disconnect Strava?": "Ngắt kết nối Strava?",
