  "Get set": "Chuẩn bị",
  "Know from your pocket whether to stay put, go back to the top of the superset or move on.": "Biết ngay từ trong túi: đứng yên, quay lại đầu superset hay sang bài tiếp.",
  "Last backup {0}": "Lần sao lưu gần nhất {0}",
