  "Last upload": "Lần tải lên gần nhất",
  "Leave empty to keep the one saved": "Để trống để giữ cái đã lưu",
  "Like 3-1-1-0: three seconds down, one at the bottom, one up.": "Ví dụ 3-1-1-0: ba giây hạ xuống, một giây ở dưới, một giây đẩy lên.",
  "Like the exercise ({0})": "Giống bài tập ({0})",
  "Link copied. Paste it into your calendar app.": "Đã sao chép liên kết. Dán vào ứng dụng lịch của bạn.",
  "Make a new link": "Tạo liên kết mới",
  "Make a new link?": "Tạo liên kết mới?",
  "Make my calendar link": "Tạo liên kết lịch của tôi",
  "New link made. The old one is gone.": "Đã tạo liên kết mới. Liên kết cũ đã biến mất.",
  "Nextcloud or any WebDAV folder, once a day": "Nextcloud hoặc thư mục WebDAV bất kỳ, mỗi ngày một lần",
