  "Steady double progression": "Tăng tiến kép đều đặn",
  "Undulating days": "Ngày luân phiên",
  "Shorter rests": "Nghỉ ngắn hơn",
  "Work up a rep range one rep at a time. Every set has to hit the target before it moves, and at the top of the range the weight goes up.": "Tăng dần trong khoảng số lần, mỗi lần một rep. Mọi hiệp phải đạt mục tiêu trước khi nó tăng, và ở đỉnh khoảng thì tăng mức tạ.",
  "Each session rotates: a medium day at your reps, a heavy day with fewer, a light day with more. The weights come from your estimated max, so they climb as you get stronger.": "Mỗi buổi luân phiên: ngày vừa với số rep của bạn, ngày nặng với ít hơn, ngày nhẹ với nhiều hơn. Mức tạ lấy từ mức tối đa ước tính, nên tăng theo khi bạn khỏe hơn.",
  "Same weight, a bit less rest each time every set is clean. At your shortest rest the weight goes up and the rest starts over.": "Cùng mức tạ, nghỉ ít hơn một chút mỗi khi mọi hiệp đều sạch. Ở mức nghỉ ngắn nhất thì tăng tạ và thời gian nghỉ bắt đầu lại.",
  "Every set hit {0}. Same weight, {1} reps this time.": "Mọi hiệp đều đạt {0}. Cùng mức tạ, lần này {1} rep.",
  "Not every set reached {0} yet. Same weight and target again ({1} of {2} to go).": "Chưa phải hiệp nào cũng đạt {0}. Cùng mức tạ và mục tiêu lần nữa (còn {1}/{2}).",
  "Every set clean. Same weight with {0}s less rest: {1}s.": "Mọi hiệp đều sạch. Cùng mức tạ, nghỉ ít hơn {0} giây: {1} giây.",
  "Clean at your shortest rest. {0} {1} less help, rest back to {2}s.": "Sạch ở mức nghỉ ngắn nhất. Bớt {0} {1} trợ lực, nghỉ trở lại {2} giây.",
  "Clean at your shortest rest. {0} {1} more, rest back to {2}s.": "Sạch ở mức nghỉ ngắn nhất. Thêm {0} {1}, nghỉ trở lại {2} giây.",
  "Stuck for {0} sessions. Same weight with more rest: {1}s.": "Chững lại {0} buổi. Cùng mức tạ, nghỉ nhiều hơn: {1} giây.",
  "Missed reps last time. Same weight and rest again ({0} of {1} to go).": "Lần trước hụt rep. Cùng mức tạ và thời gian nghỉ lần nữa (còn {0}/{1}).",
  "Heavy day: {0} reps at {1} {2}, from your estimated max of {3} {2}.": "Ngày nặng: {0} rep với {1} {2}, từ mức tối đa ước tính {3} {2}.",
  "Light day: {0} reps at {1} {2}, from your estimated max of {3} {2}.": "Ngày nhẹ: {0} rep với {1} {2}, từ mức tối đa ước tính {3} {2}.",
  "Medium day: {0} reps at {1} {2}, from your estimated max of {3} {2}.": "Ngày vừa: {0} rep với {1} {2}, từ mức tối đa ước tính {3} {2}.",
  "Rest down to (s)": "Nghỉ giảm đến (giây)",
