  // --- Settings → Garmin (garmin-146) ---
  "This version of openGym comes without the Garmin link, since Garmin’s part of it isn’t open source. The App Store, Google Play and GitHub versions have it.": "Phiên bản openGym này không có liên kết Garmin, vì phần của Garmin không phải mã nguồn mở. Bản trên App Store, Google Play và GitHub thì có.",
  "Garmin Connect isn’t on this phone. Install it, pair your watch there, then come back here.": "Điện thoại này chưa có Garmin Connect. Hãy cài đặt, ghép đôi đồng hồ ở đó rồi quay lại đây.",
  "Garmin Connect needs an update before openGym can talk to your watch.": "Cần cập nhật Garmin Connect trước khi openGym nói chuyện được với đồng hồ của bạn.",
  "Couldn’t reach Garmin Connect. Try again in a moment.": "Không kết nối được với Garmin Connect. Thử lại sau chút nữa nhé.",
  "Pick your Garmin in Garmin Connect and your workouts show up on your wrist.": "Chọn Garmin của bạn trong Garmin Connect và buổi tập sẽ hiện trên cổ tay.",
  "Garmin Connect doesn’t know a watch yet. Pair yours there first.": "Garmin Connect chưa biết đồng hồ nào. Hãy ghép đôi đồng hồ của bạn ở đó trước.",
  "openGym is on your Garmin. Sets you log on the wrist land here.": "openGym đã có trên Garmin của bạn. Các hiệp ghi trên cổ tay sẽ về đây.",
  "openGym is on your Garmin. It catches up as soon as the watch is in reach.": "openGym đã có trên Garmin của bạn. Nó sẽ cập nhật ngay khi đồng hồ ở gần.",
  "Your Garmin is here, openGym isn’t on it yet. Get it, then open it once on the watch.": "Garmin của bạn ở đây, nhưng chưa có openGym. Cài đặt rồi mở một lần trên đồng hồ.",
  "Not in reach": "Ngoài tầm",
  "openGym isn’t on it yet": "Chưa có openGym",
  "Your Garmins": "Garmin của bạn",
  "Choose watches": "Chọn đồng hồ",
  "Look again": "Tìm lại",
  "Get openGym for Garmin": "Tải openGym cho Garmin",
  "Start a workout on the phone and your Garmin asks to open openGym.": "Bắt đầu buổi tập trên điện thoại và Garmin sẽ hỏi có mở openGym không.",
