  "Every single week. That is a habit, not a phase.": "Không sót tuần nào. Đó là thói quen, không phải một giai đoạn.",
  "Every week you showed up counted.": "Mỗi tuần bạn đến đều được tính.",
  "Everything aches": "Đau khắp người",
  "Exercise of the month": "Bài tập của tháng",
  "For the Daily form card in Stats and your check-in. Read on this phone only, never sent anywhere.": "Cho thẻ Phong độ hôm nay trong Thống kê và check-in của bạn. Chỉ đọc trên điện thoại này, không gửi đi đâu.",
  "Four taps on sleep, energy, soreness and stress. On a rough day openGym offers to go lighter, and after a few weeks you see what your good days have in common.": "Bốn lần chạm về giấc ngủ, năng lượng, đau cơ và căng thẳng. Hôm nào mệt, openGym gợi ý tập nhẹ hơn, và sau vài tuần bạn sẽ thấy những ngày tốt có điểm gì chung.",
  "Frazzled": "Rối tung",
  "From Apple Health, read-only, on this phone only.": "Từ Apple Health, chỉ đọc, chỉ trên điện thoại này.",
  "From Health Connect, read-only, on this phone only.": "Từ Health Connect, chỉ đọc, chỉ trên điện thoại này.",
  "Full of beans": "Tràn đầy năng lượng",
