  "Insights show up once there is enough to compare: {0} of {1} workouts so far.": "Nhận định sẽ hiện khi đủ dữ liệu để so sánh: đến giờ {0} trên {1} buổi tập.",
  "Just today. This session sits out of progression, so your next targets stay put.": "Chỉ hôm nay. Buổi này không tính vào tiến độ, nên mục tiêu tiếp theo giữ nguyên.",
  "Leaning that way": "Nghiêng về hướng đó",
  "Lighter day: 10% off the weights. Progression sits this one out.": "Ngày nhẹ: tạ giảm 10%. Tiến độ nghỉ lần này.",
  "Lighter day: one set fewer per exercise. Progression sits this one out.": "Ngày nhẹ: bớt một hiệp mỗi bài. Tiến độ nghỉ lần này.",
  "More than last month. Momentum looks good on you.": "Nhiều hơn tháng trước. Đà này hợp với bạn đấy.",
  "New moves, new muscles asking questions. Curiosity pays.": "Động tác mới, cơ bắp mới đặt câu hỏi. Tò mò thì được đền đáp.",
  "Not a single week off. Your calendar is impressed.": "Không nghỉ tuần nào. Lịch của bạn phải nể.",
