  "Sleep, energy, soreness and stress in four taps before you train. On a rough day it offers to go lighter.": "Giấc ngủ, năng lượng, đau cơ và căng thẳng trong bốn lần chạm trước khi tập. Hôm nào mệt, nó gợi ý tập nhẹ hơn.",
