  "openGym asks Apple Health for your sleep, resting heart rate, heart rate variability and steps. Allow the ones you like. They stay on this phone, in openGym’s own file, and never go to a server.": "openGym xin Apple Health dữ liệu giấc ngủ, nhịp tim khi nghỉ, biến thiên nhịp tim và số bước của bạn. Cho phép những gì bạn muốn. Chúng ở lại trên điện thoại này, trong tệp riêng của openGym, và không bao giờ lên máy chủ.",
