  "You were sick, so this week is excused. The streak kept going and no freeze was spent.": "Bạn bị ốm nên tuần này được miễn. Chuỗi vẫn tiếp tục và không tốn lượt đóng băng nào.",
  "You were travelling, so this week is excused. The streak kept going and no freeze was spent.": "Bạn đi xa nên tuần này được miễn. Chuỗi vẫn tiếp tục và không tốn lượt đóng băng nào.",
