  "{1} is still recovering, so it sits this one out.": "{1} vẫn đang phục hồi, nên lần này nó ngồi ngoài.",
  "And it stays that way: openGym Offline has no internet permission, so Android blocks anything it might try.": "Và sẽ luôn như vậy: openGym Offline không có quyền internet, nên Android chặn mọi thứ nó định thử.",
  "Any of the sounds on your phone.": "Bất kỳ âm thanh nào trên điện thoại của bạn.",
  "Back it up now and then in Settings, Data & backup. A file on your phone is the only copy there is.": "Thỉnh thoảng hãy sao lưu trong Cài đặt, Dữ liệu và sao lưu. Một tệp trên điện thoại là bản sao duy nhất.",
  "Closing the app resets the count; the log never leaves the phone.": "Đóng ứng dụng sẽ đặt lại bộ đếm; nhật ký không bao giờ rời điện thoại.",
  "Counting since {0}, when the app started. Closing the app resets it; the log never leaves the phone.": "Đếm từ {0}, lúc ứng dụng khởi động. Đóng sẽ đặt lại; nhật ký không bao giờ rời điện thoại.",
  "Each reminder can sound different, so you know which one it is before you look.": "Mỗi lời nhắc có thể kêu khác nhau, nên bạn biết là cái nào trước khi nhìn.",
  "Everything this app asked the internet for, newest first. The address only, never what was in it.": "Mọi thứ ứng dụng này hỏi internet, mới nhất trước. Chỉ địa chỉ, không bao giờ nội dung.",
  "For reading mid-set without your glasses.": "Để đọc giữa hiệp mà không cần kính.",
