  "Last at {0}": "Lần cuối lúc {0}",
  "Latest": "Gần đây",
  "Less: no sliding, bouncing or snow. Things just appear.": "Ít hơn: không trượt, không nảy, không tuyết. Mọi thứ chỉ hiện ra.",
  "Like the phone": "Như điện thoại",
  "Mostly your own server, {0}, when there was something to sync.": "Chủ yếu là máy chủ của bạn, {0}, khi có thứ cần đồng bộ.",
  "Motion": "Chuyển động",
  "Network log": "Nhật ký mạng",
  "No map search in openGym Offline. Stand in your gym, tap Current location, done.": "openGym Offline không có tìm kiếm bản đồ. Đứng trong phòng tập, chạm Vị trí hiện tại, xong.",
  "Not a single byte left this phone. Your training is nobody’s business but yours.": "Không một byte nào rời khỏi điện thoại này. Việc tập của bạn không phải chuyện của ai khác.",
  "Nothing yet. Your server hears from this phone when there is something to sync.": "Chưa có gì. Máy chủ nghe từ điện thoại này khi có thứ cần đồng bộ.",
