  "Text size": "Cỡ chữ",
  "This is openGym Offline: Android doesn’t even let it on the internet. Want sync? The normal openGym app can do that, next to this one.": "Đây là openGym Offline: Android thậm chí không cho nó vào internet. Muốn đồng bộ? Ứng dụng openGym thường làm được, ngay bên cạnh.",
  "Weigh-ins, measurements and progress photos.": "Cân, số đo và ảnh tiến độ.",
