  "Who": "Ai",
  "Who this app talked to since you opened it.": "Ứng dụng này đã nói chuyện với ai từ khi bạn mở.",
  "Workout days and the nudge when one slips by.": "Ngày tập và cú huých khi lỡ một buổi.",
  "Workout reminders": "Lời nhắc tập luyện",
  "openGym Offline has no internet permission. Your training stays on this phone, full stop.": "openGym Offline không có quyền internet. Việc tập của bạn ở lại điện thoại này, chấm hết.",
  "openGym Offline never checks for updates, it can’t. New versions come from wherever you got this one.": "openGym Offline không bao giờ kiểm tra cập nhật, nó không thể. Phiên bản mới ở nơi bạn lấy bản này.",
