  "Forgotten workouts": "Buổi tập bị quên",
  "If nobody answers, it finishes by itself and never throws anything away. The end is your last set plus its rest, so the time stays honest. Reopen it from History for a day. Your watch asks too.": "Nếu không ai trả lời, nó tự kết thúc và không bao giờ vứt bỏ gì. Thời điểm kết thúc là hiệp cuối cộng thời gian nghỉ, nên thời gian vẫn trung thực. Có thể mở lại từ Lịch sử trong một ngày. Đồng hồ của bạn cũng hỏi.",
